#!/usr/bin/env bash
#
# A wizard walks a human through a manual procedure, step by step.
# Generated by the /wizard skill.
#
# Everything above the "STAGES" marker is the wizard library: do not hand-edit
# it. Author the per-step stages below the marker.

set -euo pipefail

# ──────────────────────────────────────────────────────────────────────────
# Wizard library: delightful, consistent UX, identical across every wizard.
# ──────────────────────────────────────────────────────────────────────────

if [[ -t 1 ]] && command -v tput >/dev/null 2>&1 && [[ "$(tput colors 2>/dev/null || echo 0)" -ge 8 ]]; then
  BOLD=$(tput bold); DIM=$(tput dim); RESET=$(tput sgr0)
  BLUE=$(tput setaf 4); GREEN=$(tput setaf 2); YELLOW=$(tput setaf 3); RED=$(tput setaf 1)
else
  BOLD=""; DIM=""; RESET=""; BLUE=""; GREEN=""; YELLOW=""; RED=""
fi

# Author sets this at the top of the stages section.
TOTAL_STAGES=0

_STAGE_INDEX=0
ENV_FILE="${ENV_FILE:-.env}"
WRITTEN_ENV=()    # KEYs written to ENV_FILE this run
WRITTEN_SECRET=() # secret NAMEs set this run
SKIPPED=()        # things we couldn't do (e.g. gh missing)

# _clear wipes the terminal so only the current step is on screen. No-op when
# output isn't a terminal, so piped logs stay readable.
_clear() {
  [[ -t 1 ]] || return 0
  if command -v tput >/dev/null 2>&1; then tput clear; else printf '\033[2J\033[3J\033[H'; fi
}

# banner "Title" shows the opening frame: what this wizard does.
banner() {
  _clear
  printf '\n%s%s  %s%s\n' "$BOLD" "$BLUE" "$1" "$RESET"
  printf '%s  %s stages%s\n\n' "$DIM" "$TOTAL_STAGES" "$RESET"
  printf '%s  You drive the browser; this wizard tells you exactly what to do and\n' "$DIM"
  printf '  captures the values you copy back. Stop any time with Ctrl-C and re-run\n'
  printf '  later, since it remembers values already saved.%s\n' "$RESET"
  pause "Ready to start?"
}

# stage "Name" clears the screen, then announces a stage and shows progress.
# Clearing keeps only the current step on screen.
stage() {
  _clear
  _STAGE_INDEX=$((_STAGE_INDEX + 1))
  printf '\n%s%s▸ Stage %s/%s · %s%s\n' \
    "$BOLD" "$BLUE" "$_STAGE_INDEX" "$TOTAL_STAGES" "$1" "$RESET"
}

# say "..." prints a plain instruction line.
say()  { printf '  %s\n' "$1"; }
# step "..." is a numbered-feeling action the human takes in the browser.
step() { printf '  %s•%s %s\n' "$BLUE" "$RESET" "$1"; }
note() { printf '  %s%s%s\n' "$DIM" "$1" "$RESET"; }
warn() { printf '  %s⚠ %s%s\n' "$YELLOW" "$1" "$RESET"; }

# open_url URL opens it in the human's browser, cross-platform incl. WSL.
open_url() {
  local url="$1"
  printf '  %s↗ opening%s %s\n' "$GREEN" "$RESET" "$url"
  { if   command -v wslview     >/dev/null 2>&1; then wslview "$url"
    elif command -v explorer.exe >/dev/null 2>&1; then explorer.exe "$url"
    elif command -v xdg-open    >/dev/null 2>&1; then xdg-open "$url"
    elif command -v open        >/dev/null 2>&1; then open "$url"
    else warn "couldn't open a browser; visit it manually: $url"; fi
  } >/dev/null 2>&1 || warn "couldn't open a browser, so visit it manually: $url"
}

# pause "msg" waits for the human to confirm they've done the manual part.
pause() {
  printf '  %s%s%s ' "$DIM" "${1:-Press Enter to continue}" "$RESET"
  read -r _ || true
}

# confirm "question" is a y/N gate; returns success on yes.
confirm() {
  local reply=""
  printf '  %s? %s [y/N] ' "$YELLOW" "$1"
  read -r reply || true
  [[ "$reply" =~ ^[Yy] ]]
}

# _existing KEY: current value of KEY in ENV_FILE, if any.
_existing() {
  [[ -f "$ENV_FILE" ]] || return 1
  local line; line=$(grep -E "^${1}=" "$ENV_FILE" | tail -n1) || return 1
  printf '%s' "${line#*=}"
}

# ask KEY "Prompt" reads a value into $KEY. Offers the existing .env value as
# a default on re-runs (Enter keeps it). Visible input (non-secret).
ask() {
  local key="$1" prompt="$2" current input
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -r input || true
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# ask_secret KEY "Prompt" is like ask, but input is hidden.
ask_secret() {
  local key="$1" prompt="$2" current input
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -rs input || true
  printf '\n'
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# write_env KEY VALUE upserts KEY=VALUE into ENV_FILE (creates it; replaces
# any existing line). Idempotent.
write_env() {
  local key="$1" value="$2" tmp
  touch "$ENV_FILE"
  tmp=$(mktemp)
  grep -vE "^${key}=" "$ENV_FILE" > "$tmp" || true
  printf '%s=%s\n' "$key" "$value" >> "$tmp"
  mv "$tmp" "$ENV_FILE"
  WRITTEN_ENV+=("$key")
  printf '  %s✓ wrote%s %s → %s\n' "$GREEN" "$RESET" "$key" "$ENV_FILE"
}

# set_secret NAME VALUE sets a GitHub Actions repo secret via gh. Falls back
# to a warning (and records it) if gh is unavailable or unauthenticated.
set_secret() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if printf '%s' "$value" | gh secret set "$name" >/dev/null 2>&1; then
      WRITTEN_SECRET+=("$name")
      printf '  %s✓ set%s GitHub secret %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub secret $name (set it manually: gh secret set $name)")
  warn "skipped GitHub secret $name: gh not ready; set it later"
}

# set_var NAME VALUE sets a GitHub Actions repo variable (non-secret).
set_var() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if gh variable set "$name" --body "$value" >/dev/null 2>&1; then
      printf '  %s✓ set%s GitHub variable %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub variable $name")
  warn "skipped GitHub variable $name, gh not ready; set it later"
}

# finish clears, then shows a closing summary of everything configured.
finish() {
  _clear
  printf '\n%s%s  ✓ Setup complete%s\n' "$BOLD" "$GREEN" "$RESET"
  (( ${#WRITTEN_ENV[@]} ))    && note "wrote ${#WRITTEN_ENV[@]} value(s) to $ENV_FILE: ${WRITTEN_ENV[*]}"
  (( ${#WRITTEN_SECRET[@]} )) && note "set ${#WRITTEN_SECRET[@]} GitHub secret(s): ${WRITTEN_SECRET[*]}"
  if (( ${#SKIPPED[@]} )); then
    printf '\n'; warn "still to do by hand:"
    for s in "${SKIPPED[@]}"; do note "  - $s"; done
  fi
  printf '\n'
}

# ──────────────────────────────────────────────────────────────────────────
# STAGES: the one-time setup that .github/workflows/release.yml needs.
# No secret is captured: trusted publishing has none. Each stage tells you what
# to click, then checks what it can with read-only gh api calls.
# ──────────────────────────────────────────────────────────────────────────

TOTAL_STAGES=7

REPO="chrislemke/agent-eda"
OWNER="chrislemke"
URL="https://github.com/$REPO"

# The checks need an authenticated gh. Without one, a stage still guides you.
if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
  GH_READY=1
else
  GH_READY=0
fi

MISSED=0

ok()   { printf '  %s✓%s %s\n' "$GREEN" "$RESET" "$1"; }
miss() { printf '  %s✗%s %s\n' "$RED" "$RESET" "$1"; MISSED=1; }

# api ... is a read-only gh api call that prints nothing when the call fails,
# for example on a 404, so the check that reads it reports a miss.
api() { gh api "$@" 2>/dev/null || true; }

# expect "what holds" VALUE: a ✓ when VALUE is "true", a ✗ for anything else.
expect() { if [[ "$2" == "true" ]]; then ok "$1"; else miss "$1"; fi; }

# verify "what" check_function runs the check, and on a miss offers to check
# again after you fix it. Saying no records the step in the closing summary.
verify() {
  local what="$1" check="$2"
  if (( ! GH_READY )); then
    SKIPPED+=("$what (gh isn't logged in, so the wizard couldn't check it)")
    warn "gh isn't logged in (gh auth login), so this step isn't checked."
    return 0
  fi
  printf '\n'
  while true; do
    MISSED=0
    "$check"
    if (( ! MISSED )); then return 0; fi
    if ! confirm "Check again after you fixed it? (N lists it as still to do)"; then
      SKIPPED+=("$what")
      return 0
    fi
  done
}

# A project with this name on the index means the pending publisher is the wrong
# kind. PyPI has no API that reads a pending publisher, so that part can't be checked.
check_name_free() {
  local host="$1" code
  code="$(curl -s -o /dev/null -w '%{http_code}' "https://$host/pypi/agent-eda/json" || true)"
  printf '\n'
  if [[ "$code" == "404" ]]; then
    ok "agent-eda isn't on $host yet. A pending publisher doesn't reserve the name."
  elif [[ "$code" == "200" ]]; then
    warn "agent-eda already exists on $host. If it is yours, add a trusted publisher in the project's Publishing settings instead of a pending one."
  else
    note "couldn't reach $host (HTTP ${code:-none}); the project page tells you whether the name is taken."
  fi
  note "PyPI can't show a pending publisher through an API: look at the list on the page once."
}

# check_environment NAME reviewer|none: the environment exists, deploys only from
# v* tags, and has (or lacks) the maintainer as the required reviewer.
check_environment() {
  local name="$1" reviewers="$2" found
  found="$(api "repos/$REPO/environments/$name" --jq '.name')"
  if [[ "$found" != "$name" ]]; then
    miss "the environment $name doesn't exist"
    return 0
  fi
  ok "the environment $name exists"
  expect "$name deploys only from selected branches and tags" \
    "$(api "repos/$REPO/environments/$name" --jq '.deployment_branch_policy.custom_branch_policies == true and .deployment_branch_policy.protected_branches == false')"
  expect "$name has the tag rule v*" \
    "$(api "repos/$REPO/environments/$name/deployment-branch-policies" --jq '[.branch_policies[] | select(.type == "tag" and .name == "v*")] | length == 1')"
  expect "$name has no branch rule" \
    "$(api "repos/$REPO/environments/$name/deployment-branch-policies" --jq '[.branch_policies[] | select((.type // "branch") != "tag")] | length == 0')"
  if [[ "$reviewers" == "reviewer" ]]; then
    expect "$OWNER is a required reviewer of $name" \
      "$(api "repos/$REPO/environments/$name" --jq "[.protection_rules[]? | select(.type == \"required_reviewers\") | .reviewers[]?.reviewer.login] | index(\"$OWNER\") != null")"
    expect "$name lets the reviewer approve their own deployment (prevent self-review is off)" \
      "$(api "repos/$REPO/environments/$name" --jq '[.protection_rules[]? | select(.type == "required_reviewers") | .prevent_self_review] | .[0] == false')"
  else
    expect "$name needs no approval" \
      "$(api "repos/$REPO/environments/$name" --jq '[.protection_rules[]? | select(.type == "required_reviewers")] | length == 0')"
  fi
}

check_environment_pypi()     { check_environment pypi reviewer; }
check_environment_testpypi() { check_environment testpypi none; }

check_tag_ruleset() {
  local id
  id="$(api "repos/$REPO/rulesets" --jq '[.[] | select(.target == "tag" and .enforcement == "active")] | .[0].id // empty')"
  if [[ -z "$id" ]]; then
    miss "no active ruleset targets tags"
    return 0
  fi
  ok "an active tag ruleset exists (id $id)"
  expect "it targets the tags v*" \
    "$(api "repos/$REPO/rulesets/$id" --jq '[.conditions.ref_name.include[]] | index("refs/tags/v*") != null')"
  expect "it restricts creating, updating and deleting tags, and blocks force pushes" \
    "$(api "repos/$REPO/rulesets/$id" --jq '[.rules[].type] | (index("creation") != null and index("update") != null and index("deletion") != null and index("non_fast_forward") != null)')"
  expect "repository admins can bypass it" \
    "$(api "repos/$REPO/rulesets/$id" --jq '[.bypass_actors[]? | select(.actor_type == "RepositoryRole" and .actor_id == 5)] | length > 0')"
}

check_immutable_releases() {
  expect "release immutability is on" "$(api "repos/$REPO/immutable-releases" --jq '.enabled')"
  note "If gh can't read this setting, look at the checkbox on the settings page instead."
}

check_actions_policy() {
  expect "only selected actions are allowed" \
    "$(api "repos/$REPO/actions/permissions" --jq '.allowed_actions == "selected"')"
  expect "actions created by GitHub are allowed" \
    "$(api "repos/$REPO/actions/permissions/selected-actions" --jq '.github_owned_allowed')"
  expect "astral-sh/setup-uv and pypa/gh-action-pypi-publish are allowed" \
    "$(api "repos/$REPO/actions/permissions/selected-actions" --jq '[.patterns_allowed[]?] | (any(startswith("astral-sh/setup-uv")) and any(startswith("pypa/gh-action-pypi-publish")))')"
  expect "actions must be pinned to a full commit SHA" \
    "$(api "repos/$REPO/actions/permissions" --jq '.sha_pinning_required')"
}

banner "agent-eda: set up publishing to PyPI"

# ── 1 ─────────────────────────────────────────────────────────────────────
stage "PyPI: a pending trusted publisher"
say "PyPI will accept uploads from release.yml without any token, once it trusts"
say "this workflow. The project doesn't exist yet, so you add a *pending* publisher."
open_url "https://pypi.org/manage/account/publishing/"
step "Log in to PyPI (create the account first if you have none, and turn on 2FA)."
step "Under 'Add a new pending publisher', pick the GitHub tab and fill in:"
say "      PyPI project name   agent-eda"
say "      Owner               $OWNER"
say "      Repository name     agent-eda"
say "      Workflow name       release.yml"
say "      Environment name    pypi"
step "Click 'Add'. The publisher shows up in the 'Pending publishers' list."
pause "Done? Press Enter to check the name."
check_name_free pypi.org

# ── 2 ─────────────────────────────────────────────────────────────────────
stage "TestPyPI: the same publisher, with its own account"
say "TestPyPI is a separate service with separate accounts. Release candidates"
say "such as 0.1.0rc1 go there, so you can rehearse without touching PyPI."
open_url "https://test.pypi.org/manage/account/publishing/"
step "Log in to TestPyPI. Register at https://test.pypi.org/account/register/ if you must."
step "Under 'Add a new pending publisher', pick the GitHub tab and fill in:"
say "      PyPI project name   agent-eda"
say "      Owner               $OWNER"
say "      Repository name     agent-eda"
say "      Workflow name       release.yml"
say "      Environment name    testpypi        (not pypi)"
step "Click 'Add'."
pause "Done? Press Enter to check the name."
check_name_free test.pypi.org

# ── 3 ─────────────────────────────────────────────────────────────────────
stage "GitHub: the environment pypi, with your approval"
say "Publishing to PyPI waits in this environment until you approve it, and the"
say "environment accepts deployments only from v* tags, never from a branch."
open_url "$URL/settings/environments/new"
step "Name it: pypi    then 'Configure environment'."
step "Tick 'Required reviewers' and add $OWNER."
step "Untick 'Prevent self-review': you are the only maintainer, so you approve your own release."
step "Click 'Save protection rules'."
step "Under 'Deployment branches and tags', choose 'Selected branches and tags'."
step "'Add deployment branch or tag rule': Ref type 'Tag', name pattern: v*    then 'Add rule'."
pause "Done? Press Enter to check."
verify "GitHub environment pypi" check_environment_pypi

# ── 4 ─────────────────────────────────────────────────────────────────────
stage "GitHub: the environment testpypi, without approval"
say "Release candidates go to TestPyPI and need no approval, but they too come"
say "only from v* tags."
open_url "$URL/settings/environments/new"
step "Name it: testpypi    then 'Configure environment'."
step "Leave 'Required reviewers' off."
step "Under 'Deployment branches and tags', choose 'Selected branches and tags'."
step "'Add deployment branch or tag rule': Ref type 'Tag', name pattern: v*    then 'Add rule'."
pause "Done? Press Enter to check."
verify "GitHub environment testpypi" check_environment_testpypi

# ── 5 ─────────────────────────────────────────────────────────────────────
stage "GitHub: protect the v* tags"
say "A release is whatever a v* tag points at, so nobody but an admin may create,"
say "move or delete one, and a force push never moves one."
open_url "$URL/settings/rules/new?target=tag"
step "Ruleset name: release tags    Enforcement status: Active."
step "Bypass list: 'Add bypass', pick the role 'Repository admin', mode 'Always allow'."
step "Target tags: 'Add target', 'Include by pattern', pattern: v*"
step "Rules: tick 'Restrict creations', 'Restrict updates', 'Restrict deletions' and 'Block force pushes'."
step "Click 'Create'."
pause "Done? Press Enter to check."
verify "the tag ruleset for v*" check_tag_ruleset

# ── 6 ─────────────────────────────────────────────────────────────────────
stage "GitHub: release immutability"
say "With it on, a published GitHub release keeps its tag and its files for good."
warn "It applies to every release made from now on, and a release can't be edited after it is published."
open_url "$URL/settings"
step "On the General page, scroll to 'Releases'."
step "Tick 'Enable release immutability'."
pause "Done? Press Enter to check."
verify "release immutability" check_immutable_releases

# ── 7 ─────────────────────────────────────────────────────────────────────
stage "GitHub: only the actions we use (optional)"
say "release.yml pins every action to a commit SHA. This setting makes GitHub refuse"
say "an action that isn't pinned or isn't on the list, so a new action is a decision."
warn "A later workflow that uses another third-party action needs it added here first."
if confirm "Set this up now?"; then
  open_url "$URL/settings/actions"
  step "Under 'Actions permissions', choose 'Allow $OWNER, and select non-$OWNER, actions and reusable workflows'."
  step "Tick 'Allow actions created by GitHub'."
  step "In the list, enter:  astral-sh/setup-uv@*, pypa/gh-action-pypi-publish@*"
  step "Tick 'Require actions to be pinned to a full-length commit SHA'."
  step "Click 'Save'."
  pause "Done? Press Enter to check."
  verify "the allow-list of actions" check_actions_policy
else
  SKIPPED+=("the allow-list of actions (optional): re-run this wizard to set it up")
fi
# ──────────────────────────────────────────────────────────────────────────

finish
note "Next: the rehearsal. Set the version to 0.1.0rc1 with 'uv version 0.1.0rc1', commit,"
note "merge, then 'git tag -a v0.1.0rc1 -m \"agent-eda 0.1.0rc1\"' and push the tag."
note "CONTRIBUTING.md, Releasing, has every step."
printf '\n'
